void setUp(void) {}
void tearDown(void) {}

#ifdef HAVE_ROM
static const uint16_t LOAD = 0x2700, SHADOW = 0x38df;  // SID register shadow of the player
static uint8_t ram[MARBLE_SID_RAM];
static SidPlayer player;
static PsidInfo info;
static const uint8_t *file = nullptr;
static int16_t buf[400];

static uint32_t crc32(const uint8_t *p, size_t n) {
  uint32_t c = ~0u;
  for (size_t i = 0; i < n; i++) {
    c ^= p[i];
    for (int k = 0; k < 8; k++) { c = c >> 1 ^ (0xedb88320 & (0 - (c & 1))); }
  }
  return ~c;
}

static void load() {
  if (!file) {
    static Asset<unsigned char, COMPRESSED> sid(marble_sid_blob);
    file = sid.data();
  }
  TEST_ASSERT_TRUE(psidParse(file, MARBLE_SID_SIZE, &info));
  TEST_ASSERT_TRUE(player.load(info, ram, MARBLE_SID_RAM));
  player.alias(0x0700, MARBLE_SID_ALIAS, 0x400);
}

static void frame() { player.render(buf, 400); }  // one 60 Hz frame at 24 kHz

static void test_file_matches_converter(void) {
  load();
  TEST_ASSERT_EQUAL_HEX32(MARBLE_SID_CRC, crc32(file, MARBLE_SID_SIZE));
  TEST_ASSERT_EQUAL(MARBLE_SID_SONGS, info.songs);
}

// every song 20 s: no C64 access outside the payload and the alias page
static void test_songs_stay_inside(void) {
  load();
  for (uint8_t s = 1; s <= info.songs; s++) {
    player.start(s);
    for (int k = 0; k < 20 * 60; k++) { frame(); }
    char msg[48];
    snprintf(msg, sizeof(msg), "song %u", s);
    TEST_ASSERT_EQUAL_MESSAGE(0, player.strays(), msg);
  }
}

// voices 1-2 of the race music, one frame
static void musicVoices(uint8_t out[14]) { memcpy(out, ram + SHADOW + 7 - LOAD, 14); }

// an effect on voice 0 over the beginner music: voices 1-2 equal a run without it
static void test_effect_keeps_music_voices(void) {
  load();
  static uint8_t solo[600][14];
  player.start(2);
  for (int k = 0; k < 600; k++) { frame(); musicVoices(solo[k]); }
  player.start(2);
  bool gate = false;
  for (int k = 0; k < 600; k++) {
    if (k == 100) { player.jsr(MARBLE_SID_FX_STUB, MARBLE_FX_31); }
    frame();
    uint8_t v[14];
    musicVoices(v);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(solo[k], v, 14);
    if (k >= 100 && k < 105) { gate = gate || (ram[SHADOW + 4 - LOAD] & 1); }
  }
  TEST_ASSERT_TRUE_MESSAGE(gate, "the effect must sound over the music (voice 0 gate)");
  TEST_ASSERT_EQUAL(0, player.strays());
}

// the effect sounds: voice 0 gate set within 5 frames of the stub call
static void test_effect_plays(void) {
  load();
  player.start(MARBLE_SID_SILENT);
  frame();
  player.jsr(MARBLE_SID_FX_STUB, MARBLE_FX_31);
  bool gate = false;
  for (int k = 0; k < 5; k++) { frame(); gate = gate || (ram[SHADOW + 4 - LOAD] & 1); }
  TEST_ASSERT_TRUE(gate);
}

// restarting slot 1 (same effect twice, two in a row) keeps the voice count at slot 0 + 1
static void test_effect_restart(void) {
  load();
  player.start(2);
  frame();
  for (int i = 0; i < 4; i++) {
    player.jsr(MARBLE_SID_FX_STUB, i & 1 ? 0 : MARBLE_FX_31);
    frame();
    TEST_ASSERT_EQUAL(2, ram[0x2728 - LOAD]);              // slots
    TEST_ASSERT_EQUAL(ram[0x272c - LOAD] + 1, ram[0x2727 - LOAD]);  // voices: music + 1
  }
  for (int k = 0; k < 600; k++) { frame(); }
  TEST_ASSERT_EQUAL(0, player.strays());
}

static void writeWav(const char *path, const int16_t *s, uint32_t n) {
  FILE *f = fopen(path, "wb");
  if (!f) { return; }
  const uint32_t rate = 24000, bytes = n * 2;
  const uint32_t hdr[] = {36 + bytes, 16, 0x00010001, rate, rate * 2, 0x00100002};
  fwrite("RIFF", 1, 4, f); fwrite(&hdr[0], 4, 1, f);
  fwrite("WAVEfmt ", 1, 8, f); fwrite(&hdr[1], 4, 5, f);
  fwrite("data", 1, 4, f); fwrite(&bytes, 4, 1, f);
  for (uint32_t i = 0; i < n; i++) { const int16_t v = s[i] * 64; fwrite(&v, 2, 1, f); }
  fclose(f);
}

// listening: SOUND_WAV_DIR=/dir writes song_N.wav (30 s) and fx_N.wav (effect N over
// silence, 3 s)
static void test_wav_dump(void) {
  const char *dir = getenv("SOUND_WAV_DIR");
  if (!dir) { TEST_IGNORE_MESSAGE("set SOUND_WAV_DIR"); }
  load();
  static int16_t out[30 * 24000];
  char path[512];
  for (uint8_t s = 1; s <= info.songs; s++) {
    player.start(s);
    player.render(out, 30 * 24000);
    snprintf(path, sizeof(path), "%s/song_%u.wav", dir, s);
    writeWav(path, out, 30 * 24000);
  }
  for (uint8_t e = 0; e < MARBLE_SID_EFFECTS; e++) {
    player.start(MARBLE_SID_SILENT);
    player.render(out, 400);
    player.jsr(MARBLE_SID_FX_STUB, e);
    player.render(out, 3 * 24000);
    snprintf(path, sizeof(path), "%s/fx_%u.wav", dir, e);
    writeWav(path, out, 3 * 24000);
  }
}
using marble_physics::Mem;
static uint8_t work[marble_physics::RAM_SIZE];
static marble_sound::Sound snd;

static void fresh() { memset(work, 0, sizeof(work)); marble_sound::reset(snd); }
static void sendStep(uint8_t c) { marble_sound::send(Mem(work, 0), c); marble_sound::step(snd); }

static void test_race_music(void) {
  fresh();
  const uint16_t r = snd.music >> 8;
  sendStep(0x0a);
  TEST_ASSERT_EQUAL(2, snd.music & 0xff);
  TEST_ASSERT_EQUAL(r + 1, snd.music >> 8);
  sendStep(0x0a);  // same piece: no restart
  TEST_ASSERT_EQUAL(r + 1, snd.music >> 8);
  sendStep(0x00);  // stop: the silent song (effects stay possible)
  TEST_ASSERT_EQUAL(MARBLE_SID_SILENT, snd.music & 0xff);
}

static void test_unknown_keeps_music(void) {
  fresh();
  sendStep(0x08);
  const uint16_t m = snd.music, e = snd.effect;
  for (uint8_t c : {0x10, 0x16, 0x1a, 0x3a, 0x3b, 0x62, 0x03, 0x07, 0x09, 0xff}) {
    sendStep(c);
    TEST_ASSERT_EQUAL_HEX16(m, snd.music);
    TEST_ASSERT_EQUAL_HEX16(e, snd.effect);
  }
}

static void test_jingle_and_effect(void) {
  fresh();
  sendStep(0x3f);
  TEST_ASSERT_EQUAL(MARBLE_SONG_3F, snd.music & 0xff);
  const uint16_t e = snd.effect;
  sendStep(0x31);
  TEST_ASSERT_EQUAL(MARBLE_FX_31, snd.effect & 0xff);
  TEST_ASSERT_EQUAL((e >> 8) + 1, snd.effect >> 8);
  sendStep(0x31);  // again: a new request (restart)
  TEST_ASSERT_EQUAL((e >> 8) + 2, snd.effect >> 8);
}

static void test_skip_word_drops(void) {
  fresh();
  Mem m(work, 0);
  m.ww(marble_sound::SKIP, 1);
  marble_sound::send(m, 0x0a);
  TEST_ASSERT_EQUAL(0, marble_sound::queued());
}

static void test_queue_overflow_drops(void) {
  fresh();
  for (int i = 0; i < 20; i++) { marble_sound::send(Mem(work, 0), 0x31); }
  TEST_ASSERT_EQUAL(marble_sound::QUEUE, marble_sound::queued());
  marble_sound::step(snd);
  TEST_ASSERT_EQUAL(0, marble_sound::queued());
}
#endif

int main(int, char **) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  Arena::init();
  Arena::reserve(&marble_arena_plan);  // like switchTo()
  marble_physics::loadRom();
  RUN_TEST(test_file_matches_converter);
  RUN_TEST(test_songs_stay_inside);
  RUN_TEST(test_effect_keeps_music_voices);
  RUN_TEST(test_effect_plays);
  RUN_TEST(test_effect_restart);
  RUN_TEST(test_wav_dump);
  RUN_TEST(test_race_music);
  RUN_TEST(test_unknown_keeps_music);
  RUN_TEST(test_jingle_and_effect);
  RUN_TEST(test_skip_word_drops);
  RUN_TEST(test_queue_overflow_drops);
#endif
  return UNITY_END();
}
